195	  if (opts.query && !pathHasQueryOrFragment(fullPath)) {
196	    fullPath = serializePathWithQuery(fullPath, opts.query)
197	  }
198	
199	  return {
200	    origin: origin.toString(),
201	    method: opts.method,
202	    path: fullPath,
203	    headers: opts.headers
204	  }
205	}
