207	function appendHeader (headers, key, val) {
208	  const headerName = key.toLowerCase()
209	  const current = headers[headerName]
210	  const values = Array.isArray(val) ? val : [val]
211	
212	  if (current === undefined) {
213	    headers[headerName] = Array.isArray(val) ? val.slice() : val
214	  } else if (Array.isArray(current)) {
215	    current.push(...values)
216	  } else {
217	    headers[headerName] = [current, ...values]
218	  }
219	}
