221	/**
222	 * @param {Record<string, string[] | string>}
223	 * @returns {Record<string, string[] | string>}
224	 */
225	function normalizeHeaders (opts) {
226	  let headers
227	  if (opts.headers == null) {
228	    headers = {}
229	  } else if (typeof opts.headers === 'object') {
230	    headers = {}
231	
232	    if (hasSafeIterator(opts.headers)) {
233	      if (Array.isArray(opts.headers)) {
234	        // Array format: could be flat alternating [k, v, k, v, ...]
235	        // or array-of-pairs [[k, v], ...]
236	        const first = opts.headers[0]
237	        if (Array.isArray(first)) {
238	          for (const x of opts.headers) {
239	            if (!Array.isArray(x)) {
240	              throw new Error('opts.headers is not a valid header map')
241	            }
242	            const [key, val] = x
243	            if (typeof key !== 'string' || typeof val !== 'string') {
