274	        for (const x of opts.headers) {
275	          if (!Array.isArray(x)) {
276	            throw new Error('opts.headers is not a valid header map')
277	          }
278	          const [key, val] = x
279	          if (typeof key !== 'string' || typeof val !== 'string') {
280	            throw new Error('opts.headers is not a valid header map')
281	          }
282	          appendHeader(headers, key, val)
283	        }
284	      }
285	    } else {
286	      for (const key of Object.keys(opts.headers)) {
287	        appendHeader(headers, key, opts.headers[key])
288	      }
289	    }
290	  } else {
291	    throw new Error('opts.headers is not an object')
292	  }
293	
294	  return headers
295	}
