464	            let fieldList = ''
465	            let lastQuotedPart = i
466	            let foundEndingQuote = false
467	            const closingQuote = findUnescapedQuote(value, 1)
468	
469	            if (closingQuote !== -1) {
470	              fieldList = value.substring(1, closingQuote)
