481	                lastQuotedPart = j
482	
483	                if (closingQuote !== -1) {
484	                  fieldListParts.push(nextPart.substring(0, closingQuote))
485	                  foundEndingQuote = true
486	                  break
487	                }
488	
489	                fieldListParts.push(nextPart)
490	              }
491	
492	              fieldList = fieldListParts.join(',')
