538	      // eslint-disable-next-line no-fallthrough
539	      case 'public':
540	      case 'must-revalidate':
541	      case 'proxy-revalidate':
542	      case 'immutable':
543	      case 'no-transform':
544	      case 'must-understand':
545	      case 'only-if-cached':
