605	/**
606	 * @param {string | string[]} varyHeader Vary header from the server
607	 * @param {Record<string, string | string[]>} headers Request headers
608	 * @returns {Record<string, string | string[] | null> | undefined}
609	 */
610	function parseVaryHeader (varyHeader, headers) {
611	  if (hasVaryStar(varyHeader)) {
612	    return headers
613	  }
614	
615	  const output = /** @type {Record<string, string | string[] | null>} */ ({})
616	
617	  const varyingHeaders = splitVaryHeader(varyHeader)
