644	
645	/**
646	 * Note: this deviates from the spec a little. Empty etags ("", W/"") are valid,
647	 *  however, including them in cached resposnes serves little to no purpose.
648	 *
649	 * @see https://www.rfc-editor.org/rfc/rfc9110.html#name-etag
650	 *
651	 * @param {string} etag
652	 * @returns {boolean}
653	 */
654	function isEtagUsable (etag) {
655	  if (etag.length <= 2) {
656	    // Shortest an etag can be is two chars (just ""). This is where we deviate
657	    //  from the spec requiring a min of 3 chars however
658	    return false
659	  }
660	
661	  if (etag[0] === '"' && etag[etag.length - 1] === '"') {
662	    // ETag: ""asd123"" or ETag: "W/"asd123"", kinda undefined behavior in the
663	    //  spec. Some servers will accept these while others don't.
664	    // ETag: "asd123"
665	    return !(etag[1] === '"' || etag.startsWith('"W/'))
666	  }
667	
668	  if (etag.startsWith('W/"') && etag[etag.length - 1] === '"') {
669	    // ETag: W/"", also where we deviate from the spec & require a min of 3
670	    //  chars
671	    // ETag: for W/"", W/"asd123"
672	    return etag.length !== 4
673	  }
674	
675	  // Anything else
676	  return false
677	}
678	
679	/**
680	 * @param {unknown} store
681	 * @returns {asserts store is import('../../types/cache-interceptor.d.ts').default.CacheStore}
682	 */
683	function assertCacheStore (store, name = 'CacheStore') {
684	  if (typeof store !== 'object' || store === null) {
685	    throw new TypeError(`expected type of ${name} to be a CacheStore, got ${store === null ? 'null' : typeof store}`)
686	  }
687	
688	  for (const fn of ['get', 'createWriteStream', 'delete']) {
689	    if (typeof store[fn] !== 'function') {
690	      throw new TypeError(`${name} needs to have a \`${fn}()\` function`)
691	    }
692	  }
693	}
694	/**
695	 * @param {unknown} methods
696	 * @returns {asserts methods is import('../../types/cache-interceptor.d.ts').default.CacheMethods[]}
697	 */
698	function assertCacheMethods (methods, name = 'CacheMethods') {
699	  if (!Array.isArray(methods)) {
700	    throw new TypeError(`expected type of ${name} needs to be an array, got ${methods === null ? 'null' : typeof methods}`)
701	  }
702	
703	  if (methods.length === 0) {
704	    throw new TypeError(`${name} needs to have at least one method`)
705	  }
706	
707	  for (const method of methods) {
708	    if (!arrayIncludes(safeHTTPMethods, method)) {
709	      throw new TypeError(`element of ${name}-array needs to be one of following values: ${safeHTTPMethods.join(', ')}, got ${method}`)
