727	
728	  if (cacheKey.headers) {
729	    const sortedHeaders = Object.keys(cacheKey.headers).sort()
730	    for (const header of sortedHeaders) {
731	      // Skip excluded headers
732	      if (excludeHeaders?.has(header.toLowerCase())) {
733	        continue
734	      }
735	      headers[header] = cacheKey.headers[header]
736	    }
737	  }
738	
739	  return JSON.stringify([cacheKey.origin, cacheKey.method, cacheKey.path, headers])
740	}
741	
742	module.exports = {
743	  getInterceptorOrigin,
744	  getRequestOrigin,
745	  makeCacheKey,
746	  normalizeHeaders,
747	  assertCacheKey,
748	  assertCacheValue,
749	  parseCacheControlHeader,
750	  hasInvalidCacheControlDirective,
751	  parseVaryHeader,
752	  hasVaryStar,
753	  isInvalidOrWildcardVaryHeader,
754	  isEtagUsable,
755	  assertCacheMethods,
756	  assertCacheStore,
757	  makeDeduplicationKey
758	}
