'use strict'

const { createServer } = require('node:http')
const { Writable } = require('node:stream')
const { Client, interceptors } = require('/tmp/cxbench-undici/2be07bf97b-file')

let hits = 0
const server = createServer((req, res) => {
  req.resume()
  hits++
  res.statusCode = 404
  res.setHeader('cache-control', 'public, s-maxage=100')
  res.end('body-' + hits)
}).listen(0, async () => {
  const stored = []
  const client = new Client('http://localhost:' + server.address().port)
    .compose(interceptors.cache({
      store: {
        get (key) {
          const entry = stored.find((e) => e.key.method === key.method && e.key.path === key.path)
          return entry ? entry.value : undefined
        },
        createWriteStream (key, value) {
          console.log('STORE WRITE for method:', key.method, 'status:', value.statusCode)
          const chunks = []
          return new Writable({
            write (chunk, encoding, cb) {
              chunks.push(chunk)
              cb()
            },
            final (cb) {
              stored.push({ key, value: Object.assign({}, value, { body: chunks }) })
              cb()
            }
          })
        },
        delete () {}
      }
    }))

  for (let i = 0; i < 2; i++) {
    const res = await client.request({ method: 'POST', path: '/x', body: 'hello' })
    console.log('POST response:', res.statusCode, await res.body.text(), '| server hits:', hits)
  }
  await client.close()
  server.close()
})
